"""Manuscript text. Every number is read from Numbers.json; nothing is typed by hand.

BLOCKS is a list of (kind, payload) consumed by build manuscript.js via Manuscript Blocks.json.
Kinds: title, abstract, keywords, h1, p, table, figure, refs, appendix_h, note.
"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
N = json.loads((HERE / "Numbers.json").read_text())
E, R, S, PNL = N["episode"], N["robustness_summary"], N["shock"], N["panel"]


MINUS = "\u2212"


def f2(x):
    return f"{x:.2f}".replace("-", MINUS)


def f3(x):
    return f"{x:.3f}".replace("-", MINUS)


def pv(x):
    return "p < 0.001" if x < 0.001 else f"p = {x:.3f}"


def pct(x, d=1):
    return f"{x:.{d}f} per cent"


def n0(x):
    return f"{int(x):,}"


def ep(m, t):
    return E[f"{m}|{t}"]


def me(epi, out, level):
    for r in N["marginal"]:
        if r["episode"] == epi and r["outcome"] == out and r["coverage_level"].startswith(level):
            return r


def rs(k):
    return R[k]


bm, cv, mp = N["breadth_mean"], N["breadth_cv"], N["material_pct"]
A_sev, A_cov = ep("A|H1|severity", "breadth_z"), ep("A|H2|severity", "coverage_z")
A_int = ep("A|H3|severity", "breadth_z:coverage_z")
A_rec, A_rec_int = ep("A|H1|recovery", "breadth_z"), ep("A|H3|recovery", "breadth_z:coverage_z")
A_marg = ep("A|H1|margin_change", "breadth_z")
B_m1, B_m2, B_sev = ep("B|H1|margin_change", "breadth_z"), ep("B|H1|margin_change_two", "breadth_z"), ep("B|H1|severity", "breadth_z")
B_cov = ep("B|H2|margin_change", "coverage_z")
me_rec0, me_rec90 = me("A", "recovery", "no"), me("A", "recovery", "90")
me_sev0, me_sev90 = me("A", "severity", "no"), me("A", "severity", "90")
rob_rec, rob_int = rs("A|recovery|breadth_z"), rs("A|severity|breadth_z:coverage_z")
rob_b2 = N["robustness_detail"]["B|margin_change_two|breadth_z|Base-year revenue of at least 100 million US dollars"]
sk = lambda m, t: S[f"Shock|{m}|{t}"]
cov18 = N["coverage_fy2018"]
pred = N["prediction"]
CASES = {c["name"]: c for c in json.loads((HERE.parent / "Results" / "Illustrative Cases.json").read_text())}
pchg = lambda x: f"{100 * (2.718281828459045 ** x - 1):.0f} per cent"
cs = lambda n: CASES[n]
au0, au1 = N["audit_original"], N["audit_revised"]
desc = N["episodeA_desc"]

TITLE = "When every risk is material: disclosed risk convergence, documented response and organisational resilience in US firms, 2017 to 2025"

ABSTRACT = [
    ("Purpose", "This study examines whether the convergence of emerging strategic risks in corporate disclosure identifies which firms lose most when systemic shocks arrive and whether documented responses to those risks protect performance."),
    ("Design/methodology/approach", f"A stratified random sample of {n0(N['sample_final'])} US non-financial firms supplied {n0(N['filings'])} annual reports for fiscal years 2017 to 2025. Dictionary measures of nine risk categories in Item 1A were validated against macro-uncertainty indices and a sentence audit and then linked to SEC financial data and to geopolitical, policy-uncertainty and supply-chain pressure indices. Pre-registered cross-sectional models examine the pandemic and 2022 shocks; firm fixed-effects panels test exposure-by-shock interactions."),
    ("Findings", f"Mean convergence breadth rose from {f2(bm['2017'])} to {f2(bm['2025'])} material categories while dispersion across firms halved. Breadth did not predict the pandemic revenue fall but predicted stronger recovery among firms reporting no documented action. Documented responses were rare and mostly routine hedging; they did not reduce losses. Losses followed specific channels: macro-financial exposure lowered growth and margins in high policy-uncertainty years, with no compounding from combined exposure."),
    ("Research limitations/implications", "Measures rest on disclosure text and nominal accounting outcomes; human double-coding of the dictionary remains outstanding."),
    ("Practical implications", "Boards should treat the risk-factor list as a compliance record and test exposure by transmission channel with operational evidence."),
    ("Originality/value", "The study gives large-sample evidence that disclosed risk convergence has become near-universal and uninformative about shock losses, separating disclosure from documented action."),
]
KEYWORDS = "Strategic risk, Risk convergence, Risk disclosure, Organisational resilience, Dynamic capabilities, Strategic foresight, Enterprise risk management, Polycrisis"

BLOCKS = []
add = lambda k, v: BLOCKS.append((k, v))

add("h1", "Introduction")
add("p", f"Boards now read annual reports in which almost every risk is listed as material. In fiscal 2017 the typical sampled US firm discussed {f2(bm['2017'])} of nine emerging risk categories at length in its risk factors; by fiscal 2025 the figure was {f2(bm['2025'])} with {pct(N['share_nine_pct']['2025'])} of firms covering all nine. The period behind this change brought a pandemic and three extreme index readings: the highest global supply-chain pressure since the index begins in 1998 (December 2021), the highest geopolitical risk since March 2003 (March 2022) and the highest US trade policy uncertainty since 1985 (April 2025) (Benigno et al., 2022; Caldara and Iacoviello, 2022; Baker et al., 2016). Scholars of systemic risk describe such periods as a polycrisis in which crises in different systems entangle and intensify each other (Lawrence et al., 2024; Helbing, 2013; Renn et al., 2019). Senior executives face the practical version of that claim when they decide how many risks deserve attention and what to do about each (Day and Dennis, 2022; Sheehan, 2020; Soleimani and Stauffer, 2026).")
add("p", "Two assumptions sit behind current practice. The first holds that firms exposed to several emerging risks at once are more fragile, because shocks that arrive together exhaust attention and slack (Ocasio, 1997; Bourgeois, 1981; Lawrence et al., 2024). The second holds that disclosure of a risk signals some capacity to manage it, so that a long and current risk register indicates preparedness (Nocco and Stulz, 2006; Hoyt and Liebenberg, 2011). Neither has been tested at scale. Research that measures risk from corporate text usually builds one category at a time, whether political risk (Hassan et al., 2019), epidemic exposure (Hassan et al., 2023), climate exposure (Sautner et al., 2023) or cyber risk (Florackis et al., 2022). Research on organisational resilience in turn rarely separates what firms disclose from what they report doing (Williams et al., 2017; Linnenluecke, 2017; Hillmann and Guenther, 2021). The closest study shows that pre-crisis disclosure of slack, learning and innovation capabilities in 10-K filings was associated with investor recognition of resilience during the pandemic (Neunsinger et al., 2026). It does not ask whether the number and combination of disclosed risks matter or whether documented action on those risks protects operating performance.")
add("p", f"This study addresses three questions. How far do emerging risks co-occur in corporate disclosure and how has that changed since 2017? Does pre-shock convergence of disclosed risk predict performance loss and recovery in systemic shocks beyond the separate effect of each category? Do firms whose documented actions cover the risks they disclose fare better? The evidence comes from {n0(N['filings'])} annual reports filed by a stratified random sample of {n0(N['sample_final'])} US non-financial firms, linked to SEC financial statement data and to four public uncertainty indices. Hypotheses, measures and decision rules were committed to the project repository before outcomes were merged with text measures and every deviation is reported. The findings challenge both assumptions. Disclosed convergence became near-universal and lost its power to separate firms; it did not predict who fell furthest in the pandemic; documented responses were rare and mostly routine; and losses followed specific transmission channels without measurable compounding. The paper contributes to strategic risk management and dynamic capabilities research by distinguishing disclosed exposure, documented action and realised sensitivity. It also gives boards a practical diagnostic for each.")

add("h1", "Risk convergence, sensing and response")
add("p", "Strategic management has long treated environmental uncertainty as a set of separable conditions to be judged one at a time, each with its own likely effect and response (Rindova and Courtney, 2020; Bundy et al., 2017; Weick et al., 2005). Enterprise risk management inherited that separability. Its frameworks ask firms to list risks, score each on likelihood and impact and aggregate the scores into a portfolio view (Nocco and Stulz, 2006; Bromiley et al., 2015; Andersen, 2008). The empirical literature that measures exposure from corporate text has mostly kept one measure per category (Hassan et al., 2019; Sautner et al., 2023; Florackis et al., 2022), although topic models and large dictionaries can recover many risk types from the same filing (Bao and Datta, 2014; Davis et al., 2020; Dyer et al., 2017). Systemic-risk scholars argue that separability misses the defining feature of the current period, in which shocks interact through shared infrastructure, supply networks and policy responses (Helbing, 2013; Renn et al., 2019; Lawrence et al., 2024). Climate science uses the term compound events for hazards whose joint impact exceeds the sum of their parts (Zscheischler et al., 2018). Supply-network studies show the same pattern in firms, where disruption travels through linked suppliers and losses exceed the direct shock (Carvalho et al., 2021; Elliott et al., 2022; Hendricks and Singhal, 2005; Baldwin and Freeman, 2022).")
add("p", "Dynamic capabilities theory explains why firms facing the same shocks perform differently. Firms sense threats and opportunities, seize them through investment and reconfigure assets as conditions change (Teece et al., 1997; Teece, 2007; Eisenhardt and Martin, 2000). Later work ties these capacities to managerial cognition and to agility under deep uncertainty (Helfat and Peteraf, 2015; Teece et al., 2016; Schilke et al., 2018; Doz and Kosonen, 2010). Strategic foresight specifies the sensing step. Ansoff (1975) argued that firms can act on weak signals before threats take full form. Longitudinal evidence links mature foresight practice to later profitability and market value (Rohrbeck and Kum, 2018; Vecchiato, 2012; Rohrbeck et al., 2015). The attention-based view adds that what executives notice and write about shapes what the organisation does. Studies of incumbents facing technical change show that attention expressed in corporate text precedes strategic action (Ocasio, 1997; Eggers and Kaplan, 2009; Nadkarni and Barr, 2008; Cho and Hambrick, 2006). Organisational ambidexterity explains how firms protect current operations while exploring new positions (March, 1991; O'Reilly and Tushman, 2013; Raisch and Birkinshaw, 2008), which matters when several threats demand simultaneous defence of the core and renewal. In this study dynamic capabilities supply the main mechanism and foresight specifies how sensing works when signals are many and linked. Ambidexterity is retained as an explanation for why some responses are affordable; the data contain no reliable measure of it, so it is not tested.")
add("p", "Convergence should make each capability harder to exercise. When several categories of risk are material at once, executive attention is divided across more domains (Ocasio, 1997; Cho and Hambrick, 2006) and responses compete for the same slack (Bourgeois, 1981). Protection against one threat can raise exposure to another, as when a firm concentrates sourcing to cut cost and so becomes more exposed to trade and geopolitical disruption (Baldwin and Freeman, 2022; Ivanov and Dolgui, 2020). Resilience research describes the capacity to absorb shocks and recover and shows that slack, prior practices and financial flexibility shape both the depth of the fall and the speed of recovery (Ortiz-de-Mandojana and Bansal, 2016; DesJardine et al., 2019; Fahlenbrach et al., 2021; Ding et al., 2021; Duchek, 2020). A firm with broad exposure is more likely to meet a systemic shock on several fronts at once with less room to move resources between them. Contributions to this journal on scenario practice, threats across partner networks and agility make the same practical point (Schoemaker, 2022; Mortlock and Osiyevskyy, 2023; Dencik et al., 2023; Schoemaker and Truumees, 2026).")
add("p", "H1. In a systemic shock, firms with greater pre-shock convergence of emerging risk exposures experience greater performance loss after accounting for the intensity of each risk category.")
add("p", "Risk disclosure is an imperfect record of risk management. Since December 2005 US registrants have had to describe their most significant risks in the annual report (Securities and Exchange Commission, 2005). Accounting research shows that these disclosures carry information about firm risk that investors use (Campbell et al., 2014; Kravet and Muslu, 2013; Hope et al., 2016). The same research documents rising length, repetition and boilerplate (Dyer et al., 2017; Cohen et al., 2020; Brown and Tucker, 2011; Lang and Stice-Lawrence, 2015), so a risk named in the risk factors may describe the hazard without any change in what the firm does. Institutional theory calls the gap between formal statements and practice decoupling (Meyer and Rowan, 1977; Westphal and Zajac, 2001; Bromley and Powell, 2012). Power (2009) argued that risk management often produces documentation that reassures rather than prepares. Selective disclosure is well documented in environmental reporting (Marquis et al., 2016). Two firms that disclose the same supply-chain exposure can differ in what they have done about it. The dynamic capabilities view predicts that the firm which has acted will absorb a shock better (Teece, 2007; Wenzel et al., 2021).")
add("p", "The study therefore separates the risks a firm discloses from the actions it reports having taken on them. Response coverage is the share of a firm's material risk categories for which its business description or management discussion reports a completed action. Coverage is still disclosure. It records actions on hazards, so its match with the risk profile indicates whether sensing has turned into seizing and reconfiguring (Teece, 2007; Day and Schoemaker, 2016; Schoemaker and Day, 2021). Figure 1 summarises the model.")
add("p", "H2. In a systemic shock, firms with greater pre-shock response coverage experience smaller performance loss and stronger recovery.")
add("p", "H3. Response coverage weakens the association between pre-shock risk convergence and performance loss.")
add("figure", "one")

add("h1", "Data and method")
add("p", f"The sampling frame started from the {n0(N['frame_float_entities'])} entities that reported a 2018 public float in SEC XBRL data. Of these, {n0(N['frame_float_half_bn'])} reported a float of at least 0.5 billion US dollars. Excluding finance and real estate together with utilities and unclassified entities and requiring a 10-K for fiscal 2018 left {n0(N['frame_eligible'])} eligible firms. A proportional stratified random sample of {n0(N['sample_drawn'])} was drawn by SIC division with a fixed seed. Before estimation {N['validation_excluded']} sampled firms were removed because their reported public float was implausible for their size, because they report in Canadian dollars or because they are blank-check companies, leaving {n0(N['sample_final'])} firms. Firms were not required to survive to 2025, so the panel is unbalanced and includes firms that were acquired or delisted. Table 1 lists the data sources and Table 2 the sample characteristics.")
add("table", "one")
add("p", f"All filings were retrieved from the SEC EDGAR submissions interface under its fair-access rules with a declared user agent, request throttling and caching, through scripts run in the project's continuous-integration workflow. For each firm and fiscal year from 2017 to 2025 the latest original 10-K was converted to text after removing numeric tables. Items 1, 1A and 7 were then located by heading patterns anchored to line starts. Item 1A was extracted from {pct(N['filings_item1a_ok_pct'])} and the management discussion from {pct(N['filings_item7_ok_pct'])} of the {n0(N['filings'])} filings; annual-report exhibits were used where the discussion was incorporated by reference. Fiscal years follow the Compustat convention. Financial data come from {n0(N['xbrl_fact_rows'])} XBRL fact rows. Annual values are those first reported for each period, so later restatements cannot leak information that was not available at the time. Revenue is the largest revenue concept reported for the year, because some filers tag only part of revenue with the contract-revenue concept. The Geopolitical Risk index, the US economic and trade policy uncertainty indices, the World Uncertainty Index and the Global Supply Chain Pressure Index were downloaded from their publishers and averaged over the twelve months ending in each firm's fiscal year-end month (Caldara and Iacoviello, 2022; Baker et al., 2016; Ahir et al., 2022; Benigno et al., 2022). Raw files, checksums, retrieval dates and code are held in the project repository.")
add("p", f"Each Item 1A sentence was assigned to any of nine categories using a dictionary of phrase patterns. The categories are geopolitical conflict, trade policy, regulatory change, cybersecurity, artificial intelligence and technology, supply chain, climate and environment, macro-financial instability and pandemic. A transparent dictionary was preferred to a trained classifier because its errors can be inspected sentence by sentence (Loughran and McDonald, 2011; Loughran and McDonald, 2016; Gentzkow et al., 2019). A category is material for a firm-year when it accounts for at least three sentences. Convergence breadth counts material categories from zero to nine. Linkage density is the share of sentences naming two or three categories; sentences naming four or more are hazard catalogues and are excluded from linkage. Documented response sentences in Items 1 and 7 have an organisational subject, a realised action verb within twelve words of a category term and no conditional modal, negation or accounting-treatment language. Response coverage is the share of material categories with at least one such sentence. Disclosure updating is one minus the cosine similarity of the content-word vector of Item 1A with the previous year's (Cohen et al., 2020; Brown and Tucker, 2011).")
add("p", f"Three validity checks used no human coding. The categories behaved as expected across industries: supply-chain language was most frequent in wholesale trade ({N['known_groups']['Wholesale trade']['supply']} per cent of sentences in fiscal 2018) and least frequent in services ({N['known_groups']['Services']['supply']} per cent), while climate language was highest in mining and construction. Geopolitical, trade and macro-financial intensity rose with the foreign share of pre-tax income (Spearman correlations of {f2(N['foreign_share_rho']['int_geopolitical']['rho'])}, {f2(N['foreign_share_rho']['int_trade']['rho'])} and {f2(N['foreign_share_rho']['int_macro']['rho'])}, n = {N['foreign_share_n']}, all p < 0.001). Across fiscal years, mean geopolitical intensity tracked the Geopolitical Risk index (r = {f2(N['tracking']['geopolitical']['r'])}), trade intensity tracked trade policy uncertainty (r = {f2(N['tracking']['trade']['r'])}) and regulatory intensity tracked regulatory policy uncertainty (r = {f2(N['tracking']['regulatory']['r'])}); supply-chain intensity did not fall back when supply pressure eased (r = {f2(N['tracking']['supply']['r'])}). An audit of a stratified sample of classified sentences then found low precision for some patterns, notably 'sanctions', which matched legal penalties as well as economic sanctions ({au0['geopolitical']['correct']} of {au0['geopolitical']['n']} geopolitical sentences correct). The dictionary was revised once and audited again on a fresh sample drawn with a different seed, where pooled category precision rose from {f2(N['audit_pooled_original'])} to {f2(N['audit_pooled_revised'])}. Precision remained lower for supply chain ({au1['supply']['correct']} of {au1['supply']['n']}) and for documented responses ({au1['action']['correct']} of {au1['action']['n']}). Of {au1['none']['n']} unclassified sentences {au1['none']['correct']} contained category content. The audit was carried out with an AI assistant and is reported as such; human double-coding of the released validation samples is the main outstanding measurement task. Results with the original dictionary are reported as a robustness check.")
add("p", f"The hypotheses were tested in two shock episodes. In the pandemic episode, severity is the log change in revenue from fiscal 2019 to fiscal 2020, margin change is the change in operating margin over the same years and recovery is the log ratio of fiscal 2022 to fiscal 2019 revenue. Predictors come from the fiscal 2018 10-K, filed before the pandemic by every firm. The 2022 episode combined war with inflation, interest-rate rises and supply pressure. Its outcomes compare fiscal 2022 and 2023 with fiscal 2021 and predictors come from the fiscal 2020 10-K. The models are ordinary least squares with two-digit SIC and fiscal year-end month fixed effects. They control for the nine category intensities and for log assets, leverage, cash to assets, return on assets, prior two-year revenue growth and log Item 1A length. Errors are clustered by two-digit SIC, with heteroskedasticity-consistent errors as a check (Petersen, 2009; Cameron et al., 2011). Continuous variables are winsorised at the 1st and 99th percentiles and convergence and coverage are standardised. A firm-year panel for fiscal 2019 to 2025 adds firm and year fixed effects with lagged predictors. Because macro indices are common to all firms in a year, their direct effects are absorbed by year effects; they enter only as interactions with each firm's fiscal 2018 exposure, a design in the spirit of exposure-by-shift research (Goldsmith-Pinkham et al., 2020; Borusyak et al., 2022). None of these models identifies causal effects of disclosure. They test whether disclosed convergence and documented response carry information about subsequent performance.")

add("h1", "Results")
add("p", f"Disclosure converged quickly. Mean breadth rose from {f2(bm['2017'])} material categories in fiscal 2017 to {f2(bm['2025'])} in fiscal 2025 (Figure 2 and Figure 3). The rise is not a change in sample composition, because the {N['balanced_firms']} firms present in every year show the same path ({f2(N['breadth_balanced']['2017'])} to {f2(N['breadth_balanced']['2025'])}). The share of firms with eight or nine material categories grew from {pct(N['share_eight_plus_pct']['2017'])} to {pct(N['share_eight_plus_pct']['2025'])}, while the coefficient of variation of breadth fell from {f3(cv['2017'])} to {f3(cv['2025'])}. Firms became more alike in what they disclose as they disclosed more. Linked sentences that connect two or three categories (geopolitical conflict disrupting supply is a typical example) rose from {pct(N['linkage_pct']['2017'],2)} to {pct(N['linkage_pct']['2025'],2)} of Item 1A sentences, so explicit reasoning about interaction remains a small part of the text. Median Item 1A length rose from {n0(N['median_item1a_words']['2017'])} to {n0(N['median_item1a_words']['2025'])} words.")
add("figure", "two")
add("figure", "three")
add("p", f"The category paths show what drove convergence (Figure 2). Material trade-policy disclosure rose from {pct(mp['trade']['2017'])} of firms in fiscal 2017 to {pct(mp['trade']['2025'])} in fiscal 2025, geopolitical disclosure from {pct(mp['geopolitical']['2017'])} to {pct(mp['geopolitical']['2025'])} and climate from {pct(mp['climate']['2017'])} to {pct(mp['climate']['2025'])}. Artificial intelligence and technological disruption stayed near one firm in five until fiscal 2022 ({pct(mp['technology']['2022'])}) and then reached {pct(mp['technology']['2025'])} in fiscal 2025. Pandemic disclosure went from {pct(mp['pandemic']['2017'])} to {pct(mp['pandemic']['2020'])} in fiscal 2020 and still stood at {pct(mp['pandemic']['2025'])} in fiscal 2025, five years after the shock. Cybersecurity, macro-financial and regulatory risks were already near saturation in 2017. The pattern is a ratchet: disclosure rises with a shock and rarely falls back. Convergence rose in every industry division (Figure 4).")
add("figure", "four")
add("p", f"Documented responses were uncommon. In fiscal 2018, {pct(100*cov18['share_zero'])} of firms reported no completed action in any of their material categories. The actions that were reported concentrated in interest-rate and currency hedging ({cov18['firms_with_action_by_category']['macro']} firms) and supply arrangements ({cov18['firms_with_action_by_category']['supply']} firms). Only {cov18['firms_with_action_by_category']['cyber']} firms reported a cybersecurity action and none a trade-policy action, although {pct(mp['trade']['2018'])} disclosed material trade risk in that year. Mean coverage doubled in fiscal 2020 ({pct(N['coverage_mean_pct']['2020'])} against {pct(N['coverage_mean_pct']['2019'])}) as firms described pandemic measures, then returned to {pct(N['coverage_mean_pct']['2025'])} by fiscal 2025. Table 2 reports descriptive statistics for the pandemic episode sample.")
add("table", "two")
add("p", f"Table 3 and Figure 5 report the hypothesis tests. In the pandemic, {pct(100*N['episodeA_share_fall'])} of firms saw revenue fall between fiscal 2019 and 2020 and {pct(100*N['episodeA_share_fall_10'])} saw a fall of more than ten per cent. Breadth was unrelated to the size of the fall (b = {f3(A_sev['b'])} per standard deviation, {pv(A_sev['p'])}, n = {A_sev['n']}) and to the change in operating margin (b = {f3(A_marg['b'])}, {pv(A_marg['p'])}). In the 2022 episode breadth was unrelated to the margin change to fiscal 2022 (b = {f3(B_m1['b'])}, {pv(B_m1['p'])}) and to revenue change to fiscal 2023 (b = {f3(B_sev['b'])}, {pv(B_sev['p'])}). Breadth was associated with a larger margin fall to fiscal 2023 with clustered errors (b = {f3(B_m2['b'])}, {pv(B_m2['p'])}) but the association lost significance with heteroskedasticity-consistent errors ({pv(B_m2['p_hc1'])}) and among firms with base-year revenue of at least 100 million US dollars (b = {f3(rob_b2['b'])}, {pv(rob_b2['p'])}), which places it in a handful of small-revenue firms with extreme margin changes. H1 is not supported. Response coverage was unrelated to severity in either episode (pandemic b = {f3(A_cov['b'])}, {pv(A_cov['p'])}; 2022 margin b = {f3(B_cov['b'])}, {pv(B_cov['p'])}), so H2 is not supported.")
add("table", "three")
add("figure", "five")
add("p", f"Two results run against the hypotheses. Breadth predicted stronger recovery: one standard deviation more pre-shock breadth went with {f3(A_rec['b'])} higher log revenue in fiscal 2022 relative to fiscal 2019 ({pv(A_rec['p'])}, n = {A_rec['n']}). The breadth by coverage interaction was negative for severity (b = {f3(A_int['b'])}, {pv(A_int['p'])}) and for recovery (b = {f3(A_rec_int['b'])}, {pv(A_rec_int['p'])}), the opposite of the sign H3 predicts. Marginal effects make the pattern concrete. Among firms reporting no documented action, breadth predicted recovery (b = {f3(me_rec0['effect'])}, {pv(me_rec0['p'])}) and had no association with the fall (b = {f3(me_sev0['effect'])}, {pv(me_sev0['p'])}). At the 90th percentile of coverage the recovery association disappeared (b = {f3(me_rec90['effect'])}, {pv(me_rec90['p'])}) and breadth leaned towards a deeper fall (b = {f3(me_sev90['effect'])}, {pv(me_sev90['p'])}). H3 is not supported.")
add("p", f"Table 4 summarises the pre-specified robustness grid. The recovery association kept its sign in {rob_rec['same_sign']} of {rob_rec['checks']} checks and was significant at the five per cent level in {rob_rec['p05']}; it weakened when the materiality threshold changed to one or five sentences and when diversity replaced breadth, so it depends on how convergence is counted. The negative interaction kept its sign in {rob_int['same_sign']} of {rob_int['checks']} checks and was significant in {rob_int['p05']}; it was weaker outside manufacturing. Results with the original dictionary were close to the main results (recovery b = {f3(N['episode_original_dictionary']['A|H1|recovery|breadth_z']['b'])}, {pv(N['episode_original_dictionary']['A|H1|recovery|breadth_z']['p'])}; severity b = {f3(N['episode_original_dictionary']['A|H1|severity|breadth_z']['b'])}, {pv(N['episode_original_dictionary']['A|H1|severity|breadth_z']['p'])}). In the firm fixed-effects panel, within-firm increases in breadth were not followed by significant changes in revenue growth (b = {f3(PNL['Panel|H1|rev_growth|L_breadth_z']['b'])}, {pv(PNL['Panel|H1|rev_growth|L_breadth_z']['p'])}, {n0(N['panel_meta']['Panel|H1|rev_growth']['n'])} firm-years), operating margin or the probability of an adverse year. Year-on-year updating of Item 1A rose from a mean of {N['updating_mean']['2019']:.3f} in fiscal 2019 to {N['updating_mean']['2020']:.3f} in fiscal 2020 and then fell back, but within-firm updating was not significantly associated with later revenue growth (b = {f3(PNL['Panel|E2|rev_growth|L_updating_z']['b'])}, {pv(PNL['Panel|E2|rev_growth|L_updating_z']['p'])}).")
add("table", "four")
add("p", f"The exposure-by-shock panel shows where losses did come from (Table 5). Firms with more macro-financial disclosure in fiscal 2018 had lower revenue growth in years of high policy uncertainty (b = {f3(sk('Separate exposures|rev_growth','x_macro')['b'])}, {pv(sk('Separate exposures|rev_growth','x_macro')['p'])}) and lower operating-margin change (b = {f3(sk('Separate exposures|d_op_margin','x_macro')['b'])}, {pv(sk('Separate exposures|d_op_margin','x_macro')['p'])}). Both associations held with industry-by-year fixed effects. Firms with more geopolitical disclosure had higher nominal revenue growth when geopolitical risk was high (b = {f3(sk('Separate exposures|rev_growth','x_geopolitical')['b'])}, {pv(sk('Separate exposures|rev_growth','x_geopolitical')['p'])}). So did firms with more supply-chain disclosure when supply pressure was high (b = {f3(sk('Separate exposures|rev_growth','x_supply')['b'])}, {pv(sk('Separate exposures|rev_growth','x_supply')['p'])}), with no margin effect in either case; the high-pressure years coincided with price inflation, so these firms passed costs into prices without widening margins. The term that captures compounding, breadth interacted with the number of indices in a high state, was close to zero for revenue (b = {f3(sk('With convergence|rev_growth','x_breadth_shocks')['b'])}, {pv(sk('With convergence|rev_growth','x_breadth_shocks')['p'])}) and margins (b = {f3(sk('With convergence|d_op_margin','x_breadth_shocks')['b'])}, {pv(sk('With convergence|d_op_margin','x_breadth_shocks')['p'])}). Exposure mattered channel by channel while combined exposure added nothing measurable.")
add("table", "five")
add("p", f"A final test asked whether the text measures help predict bad years. Models trained on outcome years up to fiscal 2022 were evaluated on fiscal 2023 to 2025 ({n0(pred['controls']['n_test'])} firm-years, adverse-year rate {pct(100*pred['controls']['adverse_rate_test'])}). Adding the convergence, coverage, linkage and intensity measures to a baseline of size, leverage, cash, profitability and disclosure length raised the area under the ROC curve for adverse years from {f3(pred['controls']['auc_adverse'])} to {f3(pred['controls plus text']['auc_adverse'])} and reduced out-of-sample explained variance in revenue growth from {f3(pred['controls']['oos_r2_growth'])} to {f3(pred['controls plus text']['oos_r2_growth'])}. Neither set of models predicts well and the disclosure measures add little.")

add("p", f"Eight cases chosen by a rule fixed before any filing text was read show what the averages conceal (Table 7). Within each combination of breadth above or below the median and documented action present or absent, the rule takes the largest firm by fiscal 2019 revenue whose revenue fell by more than ten per cent and the largest whose revenue did not fall. Ford and Amazon each disclosed {cs('Ford Motor Co')['breadth']} material categories in fiscal 2018, including geopolitical and supply-chain risk. Neither reported a documented action. Ford's revenue fell by {pchg(cs('Ford Motor Co')['severity']).lstrip('-')} in fiscal 2020 while Amazon's rose by {pchg(cs('AMAZON.COM, INC.')['severity'])}. Walmart and General Motors each disclosed {cs('Walmart Inc.')['breadth']} categories without documented action; Walmart's revenue rose by {pchg(cs('Walmart Inc.')['severity'])} and General Motors' fell by {pchg(cs('GENERAL MOTORS COMPANY')['severity']).lstrip('-')}. The pandemic reached vehicle makers and online retailers through opposite channels. Industry studies of the period document the same divergence (Ramelli and Wagner, 2020; Ding et al., 2021); the channel explains these outcomes far better than the number of risks each firm named. Among firms with documented actions the sentences classified as supply-chain actions were mostly acquisitions or logistics reorganisations: Marathon Petroleum's transfer of its refining logistics assets to MPLX, reported in its midstream segment, Caterpillar's acquisitions of ECM and Downer Freight Rail and UPS's earlier acquisition of Marken. Caterpillar's only macro-financial action was routine currency hedging. These are real actions, but they were not responses to the disclosed risks, which shows why documented coverage carries little information about preparedness.")
add("table", "seven")

add("h1", "Discussion")
add("p", "The study set out to test whether disclosed risk convergence identifies fragile firms and whether documented response protects them. The answer to both is no, with one qualification about recovery. These findings sit uneasily with the polycrisis view at firm level (Lawrence et al., 2024; Renn et al., 2019). Systemic risk may well entangle at the level of economies, yet the number of risks a firm discloses does not show who will be hit hardest. Three explanations fit the evidence. The first is homogenisation. When most firms list most risks, breadth stops separating firms, in the same way that boilerplate weakens the information in risk factors more generally (Dyer et al., 2017; Hope et al., 2016; Cohen et al., 2020). Risk reporting responds to litigation and regulatory incentives as well as to exposure (Elshandidy et al., 2018; Campbell et al., 2014). Item 1A also kept lengthening after the 2020 amendments to Item 105 required headings and a summary for long risk sections (Securities and Exchange Commission, 2020). The second explanation is that disclosed exposure differs from realised sensitivity. The shock panel shows that sensitivity runs through specific channels, so a count of categories mixes channels that hurt, channels that are neutral and channels through which firms passed costs into prices. The third is that breadth partly records organisational scope. Firms with more varied operations disclose more categories and also have more ways to recover revenue once a shock passes, which fits the recovery result among firms with no documented action and the resilience literature on diversified resources (Ortiz-de-Mandojana and Bansal, 2016; DesJardine et al., 2019; Duchek, 2020).")
add("p", "The documented-response results speak to decoupling and to dynamic capabilities. Documented action in the business description and management discussion was rare, routine where it existed and concentrated in financial hedging and supply contracts. That pattern fits the view that risk documentation and risk management are loosely coupled (Power, 2009; Meyer and Rowan, 1977; Bromley and Powell, 2012). The negative interaction suggests a further point. Firms that disclosed broad exposure and also reported actions in fiscal 2018 were probably already responding to pressure that had arrived, such as the 2018 tariffs, so reported action marks exposure in progress more than prepared capacity. That reading is consistent with the attention-based view, in which action follows realised problems as often as foresight (Ocasio, 1997; Eggers and Kaplan, 2009; Nadkarni and Barr, 2008) and with crisis research showing that firms often begin to reconfigure after the shock rather than before it (Wenzel et al., 2021; Bundy et al., 2017; Mithani, 2020). It is an interpretation, because the design cannot separate reactive action from reverse causality.")
add("p", "The theoretical contribution is to separate three constructs that strategy research and practice tend to merge: disclosed exposure, documented response and realised sensitivity. Dynamic capabilities theory locates resilience in sensing, seizing and reconfiguring (Teece, 2007; Schilke et al., 2018). The evidence suggests that sensing as recorded in mandatory disclosure has become a near-universal ritual that no longer distinguishes firms, that seizing and reconfiguring leave a thin and routine trace in the same documents and that sensitivity to shocks is better read from exposure to particular channels than from the number of risks named. For strategic foresight research the implication is that weak-signal detection should be judged by what changes in the organisation, since year-on-year updating of risk disclosure peaked in the pandemic year without predicting later performance (Ansoff, 1975; Rohrbeck and Kum, 2018; Day and Schoemaker, 2016). For enterprise risk management the results support critiques that risk registers and aggregate scores add little decision value without evidence of exposure and action (Bromiley et al., 2015; Power, 2009; Andersen, 2008).")

add("h1", "Implications for strategic leadership")
add("p", "The findings point to four practical changes, set out in Table 6 as a diagnostic that boards and executive teams can run on their own risk process. The first concerns the risk-factor list itself. A list that names all nine emerging risks, as {} of sampled firms did in fiscal 2025, tells a board little about relative exposure. The same is likely to hold for internal registers built from the same templates (Sheehan, 2020; Day and Dennis, 2022). Boards should ask management to rank risks by measured exposure, for example the share of revenue or cost passing through each channel. They should treat the published list as a compliance record.".format(pct(N['share_nine_pct']['2025'])))
add("p", "The second change concerns transmission channels. Losses in the shock years ran through specific channels. Macro-financial exposure reduced growth and margins when policy uncertainty rose, while geopolitical and supply exposure coincided with higher nominal revenue as firms repriced. A board review should therefore trace each risk to the line of the income statement it would move and to the firm's ability to pass costs on, an approach close to the scenario discipline advocated in this journal (Schoemaker, 2022; Mortlock and Osiyevskyy, 2023; Calandro, 2020). The third change concerns response evidence. Few firms could point to completed actions on the risks they disclosed and the actions they reported were mostly routine hedges. Executive teams should keep a register of completed adaptive actions such as qualifying second suppliers, relocating capacity or changing contract terms. They should then review whether each material risk has one (Teece et al., 2016; Ivanov and Dolgui, 2020; Soleimani and Stauffer, 2026).")
add("p", "The fourth change concerns interaction. The evidence found no extra loss from combined exposure, so boards should not assume that more risks mean more fragility. They should instead look for the few explicit links that matter, such as a geopolitical event that would cut a single-source supply route, because linked reasoning made up about three per cent of risk text even in fiscal 2025. Scenario work that combines two or three named channels is more useful than a register that lists everything (Schoemaker and Day, 2021; Dencik et al., 2023; Welch, 2026). These recommendations follow from associations in public disclosure and accounting data and should be tested inside individual organisations before they are adopted as policy.")
add("table", "six")

add("h1", "Limitations and further research")
add("p", "Several limitations qualify the findings. The measures rest on disclosure text, which reflects legal incentives as well as exposure. The dictionary was also revised once after the first estimation following an audit carried out with an AI assistant; human double-coding of the released validation samples is required before the measures are treated as validated. Precision for supply-chain risk and for documented responses remained moderate while recall is incomplete, which biases associations towards zero. Outcomes are nominal accounting measures, so inflation in 2021 and 2022 affects revenue comparisons; share prices, real output and survival would test resilience in other ways (DesJardine et al., 2019; Ramelli and Wagner, 2020). The sample covers large US non-financial firms, so results may not hold for smaller firms, financial institutions or other disclosure regimes (Elshandidy et al., 2018). The episode models rely on two shocks and on industry clustering with about fifty clusters. The exposure-by-shock design identifies differential sensitivity under the assumption that fiscal 2018 exposure was not chosen in anticipation of later shocks (Borusyak et al., 2022). None of the estimates is causal. Further research could link disclosure to operational data on suppliers, facilities and contracts, use transformer models to separate generic from specific risk language and study whether boards that rank risks by measured exposure respond faster.")

add("h1", "Conclusion")
add("p", f"Between fiscal 2017 and 2025 US firms converged on disclosing almost every emerging strategic risk. That convergence did not identify the firms that lost most in the pandemic or the 2022 shocks, documented responses were too rare and routine to protect performance and losses ran through particular channels without measurable compounding. For strategy scholars the results separate disclosed exposure, documented action and realised sensitivity, three constructs that dynamic capabilities and risk management research often treat as one. For leaders the message is direct: a longer risk list is a compliance output while resilience depends on knowing which channels move the income statement and on completed actions against them.")
